import json,pathlib
P=pathlib.Path(__file__).parent
names=['food','theology','literature','restoration','shoreline']
S={n:json.loads((P.parent/'v3'/(n+'.json')).read_text()) for n in names}
def desc(n,d):
 for it in S[n]['items']:
  if it['id'] in d:it['description']=d[it['id']]
completion={
'food':['Flatbread and fruit juice: enough for the road. The caravan can leave.','A risen loaf and a bowl of yogurt. Two different cultures have changed what we brought.','A fruit tart and puff pastry: the butter made two very different textures.','The filled sponge cake is wrapped for its journey. From hearth to cake line, our short kitchen tour is complete.'],
'theology':['The guest has a meal waiting, and the washstand is ready. Now the novice brings a question about today’s fast.','For this ordinary fast, the host may eat with the guest; the brothers keep their usual practice. Both parts of the rule remain visible.','The shared table is prepared. Hospitality has made room for the traveller without turning one limited exception into a rule for everyone.'],
'literature':['The station poem is on the page. Now we can hear what its lines might do.','The revised poem has its returning phrase and a shorter third line. It is ready for the little press.','The poem is stitched into a chapbook. What began as a sound on an empty platform can now travel with a reader.'],
'restoration':['The map’s condition is recorded. Its old marks remain; we have documented them, not erased them.','The same map is supported and housed. It is ready for careful display.','The map is on protected display with an honestly qualified story. Its survival—and what we still do not know—remain visible.'],
'shoreline':['The tide and site records now support a plan for this fictional sheltered bank.','The planted coir module is in place at the sheltered bank. Installation is the beginning of watching, not proof of success.','The season report is ready. We have a record to assess, not a guarantee that the shoreline has recovered.']}
for n,lines in completion.items():
 for st,line in zip(S[n]['stages'],lines):st['completionText']=line
