for n,s in S.items():
 missing=[i['id'] for i in s['items'] if not i.get('description')];assert not missing,(n,missing)
 s['notes'].append('Presentation v5: stage completion acknowledgments and readable pre-use contents. Recipe graph unchanged from v3; no added quotas, themes or mechanics.')
 (P/(n+'.json')).write_text(json.dumps(s,ensure_ascii=False,indent=2)+'\n')
